import{_ as a,o as r,c as s,a2 as n}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Persistent shared colony","description":"","frontmatter":{"pageId":"players/coop","contentRevision":1},"headers":[],"relativePath":"en/players/coop.md","filePath":"en/players/coop.md"}'),o={name:"en/players/coop.md"};function t(i,e,l,h,c,d){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="persistent-shared-colony" tabindex="-1">Persistent shared colony <a class="header-anchor" href="#persistent-shared-colony" aria-label="Permalink to &quot;Persistent shared colony&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol><li>The owner opens <strong>Shared colony</strong> below chat and invites a partner.</li><li>The partner opens the same window, refreshes and accepts.</li><li>The owner assigns free colonists on the home map.</li><li>From their own home colony, the partner chooses <strong>Join colony</strong>. Their home is saved before loading the mirror.</li><li>The partner controls assigned pawns, including work, schedules, equipment and combat; the owner continues playing and writes the only canonical save.</li></ol><p>Membership survives restart. Changing assignments or revoking membership ends the current session. The partner leaves to return home.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>One concurrent partner, up to 8 invitations/members and 32 pawns. The owner must be online at home. Wallet, transfer and admin permissions are not shared. Reset removes membership; archive/restore preserves it; rollback keeps membership but clears assignments. Owner pawns are not mailed to the partner.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: the active map</a></li><li><a href="./../admins/administration">Panel and moderation</a></li><li><a href="./saves-recovery">Saves and recovery</a></li></ul>',9)])])}const u=a(o,[["render",t]]);export{m as __pageData,u as default};
